<div class="admin-form-width"><section class="panel settings-panel"><div class="panel-header"><div><h2>My Account</h2><p>Account details and password security.</p></div><span class="pill pill-neutral"><?= $user['role']==='super_admin'?'Super Admin':'Admin' ?></span></div><div class="form-section"><div class="ops-list"><div class="ops-metric"><span>Name</span><strong><?= e($user['name']) ?></strong></div><div class="ops-metric"><span>Email</span><strong><?= e($user['email']) ?></strong></div><div class="ops-metric"><span>Last login</span><strong><?= e(display_date($user['last_login_at'])) ?></strong></div></div></div><div class="form-section"><h3>Change password</h3><p>Minimum 8 characters. Other sessions will be invalidated.</p><form method="post" action="<?= e(admin_url('account')) ?>"><?= \Monitor\Core\Security::csrfField() ?><label>Current password<input name="current_password" type="password" autocomplete="current-password" required></label><div class="field-grid"><label>New password<input name="password" type="password" minlength="8" maxlength="256" autocomplete="new-password" required></label><label>Confirm new password<input name="confirm_password" type="password" minlength="8" maxlength="256" autocomplete="new-password" required></label></div><div class="action-row"><button type="submit" class="button primary">Update password</button></div></form></div></section></div>